def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    rich_threats = 0
    desperate_threats = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY * 4:
                rich_threats += 1
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                desperate_threats += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive:
        return float(min(budget, 8.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    loose_supply = supply >= 22

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 2

    if tight_supply:
        urgency += 2
    elif loose_supply:
        urgency -= 1

    if desperate_threats >= 2:
        urgency += 1

    if day >= 8:
        urgency += 1

    if highest_prev >= 80:
        if urgency <= 1:
            bid = 6.0 if loose_supply else 10.0
        elif urgency <= 3:
            bid = 38.0 if tight_supply else 28.0
        else:
            bid = 82.0
    else:
        if urgency <= 0:
            bid = 7.0 if loose_supply else 11.0
        elif urgency == 1:
            bid = max(16.0, avg_prev * 0.75)
        elif urgency == 2:
            bid = max(24.0, highest_prev + 1.2)
        elif urgency == 3:
            bid = max(36.0, highest_prev + 2.0)
        elif urgency == 4:
            bid = max(52.0, highest_prev + 3.0)
        else:
            bid = max(72.0, highest_prev + 4.0)

    if rich_threats >= 1 and tight_supply and urgency >= 3:
        bid += 6.0

    reserve_floor = 0.0
    if hp > 4 and day <= 7:
        reserve_floor = DAILY_SALARY * 1.2
    max_affordable = max(0.0, budget - reserve_floor)
    if urgency >= 4:
        max_affordable = budget

    if max_affordable <= 0:
        bid = min(budget, 10.0 if urgency <= 1 else 25.0)
    else:
        bid = min(bid, max_affordable)

    if hp <= 2 or no_water >= 2:
        bid = min(budget, max(bid, 78.0))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return float(min(my_status['budget'], 20.0))

    # Aggressive bidding strategy to compete with Cindy/Bob
    # If supply is tight, bid higher to ensure survival
    base_bid = 75.0
    if supply < 20.0:
        base_bid = 95.0

    # Adjust for survival
    if my_status['hp'] <= 3:
        base_bid = min(my_status['budget'], 120.0)

    # Check for budget constraints
    bid = min(my_status['budget'], float(base_bid))
    return float(bid)
